"""Nominal identifiers shared across feature boundaries; generated by callers."""

from typing import NewType
from uuid import UUID

CaseId = NewType("CaseId", UUID)
RunId = NewType("RunId", UUID)
ConclusionId = NewType("ConclusionId", UUID)
ReviewId = NewType("ReviewId", UUID)
ReviewerId = NewType("ReviewerId", UUID)
ReferenceId = NewType("ReferenceId", UUID)
